class Solution {
public:
    int firstCompleteIndex(std::vector<int>& arr, std::vector<std::vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        std::vector<std::pair<int, int>> pos(m * n + 1);
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pos[mat[r][c]] = {r, c};
            }
        }
        std::vector<int> row_count(m, 0), col_count(n, 0);
        for (int i = 0; i < (int)arr.size(); i++) {
            auto [r, c] = pos[arr[i]];
            row_count[r]++;
            col_count[c]++;
            if (row_count[r] == n || col_count[c] == m) return i;
        }
        return -1;
    }
};

class Solution {
    public int firstCompleteIndex(int[] arr, int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[][] pos = new int[m * n + 1][2];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pos[mat[r][c]][0] = r;
                pos[mat[r][c]][1] = c;
            }
        }
        int[] rowCount = new int[m];
        int[] colCount = new int[n];
        for (int i = 0; i < arr.length; i++) {
            int r = pos[arr[i]][0];
            int c = pos[arr[i]][1];
            rowCount[r]++;
            colCount[c]++;
            if (rowCount[r] == n || colCount[c] == m) return i;
        }
        return -1;
    }
}

var firstCompleteIndex = function(arr, mat) {
    const m = mat.length, n = mat[0].length;
    const pos = new Array(m * n + 1);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            pos[mat[r][c]] = [r, c];
        }
    }
    const rowCount = new Array(m).fill(0);
    const colCount = new Array(n).fill(0);
    for (let i = 0; i < arr.length; i++) {
        const [r, c] = pos[arr[i]];
        rowCount[r]++;
        colCount[c]++;
        if (rowCount[r] === n || colCount[c] === m) return i;
    }
    return -1;
};
